const bridge = "sergeant-major" === "call-bridge";
const rank = card => card % 13;
const suit = card => Math.floor(card / 13);
const seatCount = bridge ? 4 : 3;
const handSize = bridge ? 13 : 16;
function legal(s) {
  const hand = s.hands[s.seat];
  if (!s.trick.length) return hand;
  const follow = hand.filter(c=>suit(c)===suit(s.trick[0].card));
  if(follow.length)return follow;
  if(!bridge)return hand;
  const spades=hand.filter(c=>suit(c)===3);
  const high=Math.max(-1,...s.trick.filter(x=>suit(x.card)===3).map(x=>rank(x.card)));
  const beating=spades.filter(c=>rank(c)>high);
  return beating.length?beating:hand;
}
const game={
 newMatch(ctx){
  let seed=2166136261;
  for(const p of ctx.players)for(const c of p.id)seed=Math.imul(seed^c.charCodeAt(0),16777619);
  const deck=Array.from({length:52},(_,i)=>i);
  for(let i=51;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[deck[i],deck[j]]=[deck[j],deck[i]];}
  const hands=ctx.players.map((_,i)=>deck.slice(i*handSize,(i+1)*handSize));
  return {state:{hands,kitty:deck.slice(seatCount*handSize),seat:0,trump:bridge?3:-1,bids:bridge?[-1,-1,-1,-1]:[8,5,3],scores:ctx.players.map(()=>0),trick:[],winners:[]},turn:[ctx.players[0].id]};
 },
 applyMove(s,id,m,ctx){
  const invalid=()=>{throw new InvalidMove("Choose a legal move on your turn.");};
  if(!m||Object.keys(m).length!==1||s.winners.length||id!==ctx.players[s.seat].id)invalid();
  const next={...s,seat:(s.seat+1)%seatCount};
  if(bridge&&s.bids[s.seat]<0){
   if(!Number.isInteger(m.bid)||m.bid<2||m.bid>8)invalid();
   next.bids=[...s.bids];next.bids[s.seat]=m.bid;
   return {state:next,turn:[ctx.players[next.seat].id]};
  }
  if(!bridge&&s.trump<0){
   if(!Number.isInteger(m.trump)||m.trump<0||m.trump>3)invalid();
   next.trump=m.trump;
   next.hands=s.hands.map((hand,i)=>i===0?[...hand,...s.kitty]:hand);
   next.seat=0;
   return {state:next,turn:[id]};
  }
  if(!bridge&&s.hands[0].length>handSize){
   if(!s.hands[0].includes(m.discard))invalid();
   next.hands=s.hands.map((hand,i)=>i===0?hand.filter(c=>c!==m.discard):hand);
   next.seat=next.hands[0].length===handSize?1:0;
   return {state:next,turn:[ctx.players[next.seat].id]};
  }
  if(!legal(s).includes(m.card))invalid();
  next.hands=s.hands.map((hand,i)=>i===s.seat?hand.filter(c=>c!==m.card):hand);
  next.trick=[...s.trick,{seat:s.seat,card:m.card}];
  if(next.trick.length===seatCount){
   const lead=suit(next.trick[0].card);
   const strength=c=>rank(c)+(suit(c)===s.trump?26:suit(c)===lead?13:0);
   next.seat=next.trick.reduce((a,b)=>strength(b.card)>strength(a.card)?b:a).seat;
   next.trick=[];
   next.scores=[...s.scores];next.scores[next.seat]++;
   if(next.hands.every(h=>!h.length)){
    const totals=next.scores.map((tricks,i)=>bridge?
      (tricks>=s.bids[i]?10*s.bids[i]+tricks-s.bids[i]:-10*s.bids[i]):tricks-s.bids[i]);
    next.winners=totals.flatMap((score,i)=>score===Math.max(...totals)?[i]:[]);
   }
  }
  if(!next.winners.length)return {state:next,turn:[ctx.players[next.seat].id]};
  const humans=ctx.players.filter(p=>p.kind==="human"&&p.active!==false);
  const eligible=humans.filter(p=>next.winners.includes(ctx.players.indexOf(p)));
  const paid=eligible.length?eligible:humans;
  return {state:next,turn:null,payouts:Object.fromEntries(paid.map((p,i)=>[p.id,Math.floor(ctx.pot/paid.length)+(i<ctx.pot%paid.length?1:0)]))};
 },
 viewFor(s,id,ctx){
  const {hands,kitty,...visible}=s;
  const i=ctx.players.findIndex(p=>p.id===id);
  return {...visible,hand:hands[i]??[],legal:i===s.seat&&!s.winners.length?legal(s):[],discarding:!bridge&&hands[0].length>handSize};
 },
 computerMove(s){
  if(bridge&&s.bids[s.seat]<0)return {bid:Math.max(2,Math.min(8,s.hands[s.seat].filter(c=>rank(c)>=10).length))};
  if(!bridge&&s.trump<0)return {trump:suit(s.hands[0][0])};
  if(!bridge&&s.hands[0].length>handSize)return {discard:s.hands[0][0]};
  return {card:legal(s)[0]};
 },
 randomMove(s,id,ctx){
  if((bridge&&s.bids[s.seat]<0)||(!bridge&&(s.trump<0||s.hands[0].length>handSize)))return this.computerMove(s);
  const cards=legal(s);return {card:cards[Math.floor(ctx.random()*cards.length)]};
 }
};

